server.tool(
  "search_news",
  "Search for news articles about an organisation or topic. Use for media coverage collection.",
  {
    query: external_exports.string().describe("Search query, e.g. 'WRI India air quality 2026'"),
    date_from: external_exports.string().optional().describe("Filter from date YYYY-MM-DD"),
    date_to: external_exports.string().optional().describe("Filter to date YYYY-MM-DD"),
    limit: external_exports.number().optional().describe("Max results, default 10")
  },
  async ({ query, date_from, date_to, limit }) => {
    const key = cfg().FIRECRAWL_KEY;
    if (!key) return { content: [{ type: "text", text: "ERROR: FIRECRAWL_KEY not configured" }], isError: true };
    callTracker.firecrawlSearches++;
    const body = { query, limit: limit ?? 10, lang: "en" };
    const toTbsDate = (d) => {
      const [y, m, day] = d.split("-");
      return `${Number(m)}/${Number(day)}/${y}`;
    };
    if (date_from || date_to) {
      const parts = ["cdr:1"];
      if (date_from) parts.push(`cd_min:${toTbsDate(date_from)}`);
      if (date_to) parts.push(`cd_max:${toTbsDate(date_to)}`);
      body.tbs = parts.join(",");
    }
    const r = await apiFetch("https://api.firecrawl.dev/v2/search", {
      method: "POST",
      headers: { "Content-Type": "application/json", "Authorization": `Bearer ${key}` },
      body: JSON.stringify(body)
    });
    if (!r.ok) return { content: [{ type: "text", text: `Search failed (${r.status}): ${JSON.stringify(r.data)}` }], isError: true };
    const raw = r.data?.data ?? r.data?.results ?? [];
    let results;
    if (Array.isArray(raw)) {
      results = raw;
    } else if (raw && typeof raw === "object") {
      results = Object.values(raw).flatMap((v) => Array.isArray(v) ? v : []);
    } else {
      results = [];
    }
    const verified = await Promise.all(results.map(async (a) => {
      const urlStr = String(a.url ?? "");
      if (!urlStr) return { ...a, url_ok: false, url_status: 0 };
      try {
        const ctl = new AbortController();
        const t = setTimeout(() => ctl.abort(), 6e3);
        const res = await fetch(urlStr, { method: "HEAD", signal: ctl.signal, redirect: "follow" });
        clearTimeout(t);
        return { ...a, url_ok: res.ok, url_status: res.status };
      } catch {
        return { ...a, url_ok: false, url_status: 0 };
      }
    }));
    const formatted = verified.map(
      (a, i) => `${i + 1}. ${a.title}
   URL: ${a.url}${a.url_ok ? "" : ` \u26A0\uFE0F URL_UNVERIFIED (HTTP ${a.url_status})`}
   Date: ${a.publishedDate ?? a.date ?? "unknown"}
   ${String(a.description ?? a.snippet ?? "").slice(0, 200)}`
    ).join("\n\n");
    return { content: [{ type: "text", text: formatted || "No results found." }] };
  }
);
