    if (!Object.keys(allMetrics).length) {
      return { content: [{ type: "text", text: org_name ? `No saved metrics found for "${org_name}".` : "No metrics loaded." }] };
    }
    const lines = [`Question: ${question}`, "", "=== SAVED METRICS ===", ""];
    for (const [org, history] of Object.entries(allMetrics)) {
      lines.push(`\u2500\u2500 ${org} (${history.length} report(s)) \u2500\u2500`);
      for (const entry of history) {
        const period = `${entry.date_from ?? "?"}  \u2192  ${entry.date_to ?? "?"}`;
        lines.push(`  Period: ${period}`);
        const fields = [
          ["Social", entry.social_score],
          ["Media", entry.media_score],
          ["AEO", entry.aeo_score],
          ["Overall", entry.overall_score],
          ["LI posts", entry.li_posts],
          ["LI ER%", entry.li_er],
          ["X posts", entry.tw_posts],
          ["X followers", entry.tw_followers],
          ["IG posts", entry.ig_posts],
          ["IG followers", entry.ig_followers],
          ["YT subs", entry.yt_subscribers],
          ["YT videos", entry.yt_videos],
          ["Online articles", entry.media_online],
          ["Print", entry.media_print],
          ["TV", entry.media_tv]
        ];
        for (const [k, v] of fields) {
          if (v !== void 0 && v !== null) lines.push(`    ${k}: ${v}`);
        }
        lines.push("");
      }
    }
